import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { FaGlobe, FaChevronDown } from 'react-icons/fa';
import styles from './LanguageSelector.module.css';

// Available languages with their native names
const languages = [
  { code: 'en', name: 'English', flag: '🇺🇸' },
  { code: 'es', name: 'Español', flag: '🇪🇸' },
  { code: 'fr', name: 'Français', flag: '🇫🇷' },
  { code: 'de', name: 'Deutsch', flag: '🇩🇪' },
  { code: 'zh', name: '中文', flag: '🇨🇳' },
  { code: 'ja', name: '日本語', flag: '🇯🇵' },
  { code: 'ar', name: 'العربية', flag: '🇸🇦' },
  { code: 'hi', name: 'हिन्दी', flag: '🇮🇳' },
  { code: 'pt', name: 'Português', flag: '🇧🇷' },
  { code: 'ru', name: 'Русский', flag: '🇷🇺' },
];

const LanguageSelector = () => {
  const { i18n } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  
  // Get current language
  const currentLanguage = languages.find(lang => lang.code === i18n.language) || languages[0];
  
  // Toggle dropdown
  const toggleDropdown = () => {
    setIsOpen(!isOpen);
  };
  
  // Change language
  const changeLanguage = (langCode) => {
    i18n.changeLanguage(langCode);
    setIsOpen(false);
    
    // Store language preference
    localStorage.setItem('i18nextLng', langCode);
  };
  
  return (
    <div className={styles.languageSelector}>
      <button 
        className={styles.languageButton} 
        onClick={toggleDropdown}
        aria-haspopup="true"
        aria-expanded={isOpen}
        aria-label="Select language"
      >
        <span className={styles.currentFlag}>{currentLanguage.flag}</span>
        <span className={styles.currentLanguage}>{currentLanguage.name}</span>
        <FaChevronDown className={styles.chevron} />
      </button>
      
      {isOpen && (
        <div className={styles.dropdown} role="menu">
          {languages.map((language) => (
            <button
              key={language.code}
              className={`${styles.languageOption} ${language.code === i18n.language ? styles.active : ''}`}
              onClick={() => changeLanguage(language.code)}
              role="menuitem"
            >
              <span className={styles.flag}>{language.flag}</span>
              <span className={styles.name}>{language.name}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

export default LanguageSelector;
